# owner: platform
"""Finding the stretches of opening hours nobody covers."""

from hourglass.models import Span
from hourglass.merging import merge_spans

def _clock(minute: int) -> str:
    return f"{minute // 60:02d}:{minute % 60:02d}"

def _label(begin: int, stop: int) -> str:
    return (
        f"gap {_clock(begin)}-{_clock(stop)} "
        f"({stop - begin} min)"
    )

def _check_inside(spans, opening: Span) -> None:
    for span in spans:
        low, high = opening.start, opening.end
        if span.start < low or span.end > high:
            raise ValueError(f"outside hours: {span}")

def _gap_pairs(spans, opening: Span):
    starts = [opening.start] + [span.end for span in spans]
    ends = [span.start for span in spans] + [opening.end]
    return zip(starts, ends)

def find_gaps(worked, opening: Span) -> list:
    """One label per uncovered stretch."""
    spans = merge_spans(worked)
    _check_inside(spans, opening)
    pairs = _gap_pairs(spans, opening)
    return [
        _label(begin, stop)
        for begin, stop in pairs
        if stop > begin
    ]
